sys_script.script:
(function executeRule(current, previous) {
    try {
        gs.info("Business Rule Triggered for Task: " + current.number);

        var rm = new sn_ws.RESTMessageV2('Notify External Event System', 'Send Event Notification'); // Same REST Message

        // Set task-related parameters
        rm.setStringParameterNoEscape('u_task_name', current.task_name.toString());
        rm.setStringParameterNoEscape('u_event_id', current.event_id.toString());
        rm.setStringParameterNoEscape('u_assigned_to', current.assigned_to.getDisplayValue());
        rm.setStringParameterNoEscape('u_due_date', current.due_date.toString());
        rm.setStringParameterNoEscape('u_status', current.status.toString());

        var response = rm.execute();
        var status = response.getStatusCode();
        var body = response.getBody();

        gs.info("Task Notification Sent. Status: " + status + ". Response: " + body);
    } catch (ex) {
        gs.error("Error sending task notification: " + ex.message);
    }
})(current, previous);
